INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(37611, 'Psalms 135:10', 'Psalms', 135, 10, 'هغه له منځه یووړل ډېر قومونه او هغه مړه کړل زورور پاچاهان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_10.mp3', '', 1761754199, 1761754199),
(37612, 'Psalms 135:11', 'Psalms', 135, 11, 'یعنې سیحون د اموریانو پاچا عوج د باشان پاچا او د کنعان ټول پاچاهان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_11.mp3', '', 1761754199, 1761754199),
(37613, 'Psalms 135:12', 'Psalms', 135, 12, 'د هغوی هېوادونه یې خپل قوم ته په میراث کې ورکړل یعنې اسراییلو ته چې د هغه خپل قوم ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_12.mp3', '', 1761754199, 1761754199),
(37614, 'Psalms 135:13', 'Psalms', 135, 13, 'څښتنه، نوم به دې همېش یادیږي او یادوي به ټول نسلونه تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_13.mp3', '', 1761754199, 1761754199),
(37615, 'Psalms 135:14', 'Psalms', 135, 14, 'څښتن کوي به دفاع له خپلو خلکو څخه هغه به رحم کوي خپل خادمانو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_14.mp3', '', 1761754199, 1761754199),
(37616, 'Psalms 135:15', 'Psalms', 135, 15, 'د نورو قومونو بتان جوړ دي له سرو او سپینو زرو څخه هغه جوړ شوي د انسان په لاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_15.mp3', '', 1761754199, 1761754199),
(37617, 'Psalms 135:16', 'Psalms', 135, 16, 'د هغوی خولې شته، خو خبرې پرې کولای نه شي سترګې یې شته، خو پرې لیدلی نه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_16.mp3', '', 1761754199, 1761754199),
(37618, 'Psalms 135:17', 'Psalms', 135, 17, 'غوږونه یې شته، خو پرې اورېدلی نه شي په خپلو خولو باندې ساه اخیستلی نه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_17.mp3', '', 1761754199, 1761754199),
(37619, 'Psalms 135:18', 'Psalms', 135, 18, 'چې جوړوي څوک هغه او څوک چې باور پرې لري هغوی دې شي هغو بتانو په شان چې جوړوي هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_18.mp3', '', 1761754199, 1761754199),
(37620, 'Psalms 135:19', 'Psalms', 135, 19, 'ای د اسراییلو قومه، ووایئ ثنا د څښتن ای د هارون کورنۍ، د هغه ثنا ووایئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_19.mp3', '', 1761754199, 1761754199),
(37621, 'Psalms 135:20', 'Psalms', 135, 20, 'ای د لاوي قبیلې، ووایئ ثنا د څښتن ای ټولو خلکو چې کړئ وېره له څښتنه ووایئ ثنا د څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_20.mp3', '', 1761754199, 1761754199),
(37622, 'Psalms 135:21', 'Psalms', 135, 21, 'په صهیون کې د څښتن ثنا او صفت ووایئ د هغه چا چې اوسیږي اورشلیم کې د څښتن ثنا او صفت وکړئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_21.mp3', '', 1761754199, 1761754199),
(37623, 'Jeremiah 28:1', 'Jeremiah', 28, 1, 'د يهوداه د بادشاه د صدقياه د بادشاهۍ په تازه ورځو کښې په هم هغه کال په پينځمه مياشت په څلورم کال د جبعون د ښار يو پېغمبر د عزور زوئ حننياه د مالِک خُدائ په کور کښې د اِمامانو او د خلقو په وړاندې ما ته خبرې وکړې او راته يې وفرمائيل چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_1.mp3', '', 1761754199, 1761754199),
(37624, 'Jeremiah 28:2', 'Jeremiah', 28, 2, 'مالِک خُدائ ربُ الافواج، د بنى اِسرائيلو خُدائ پاک فرمائى چې، ”زۀ به د بابل د بادشاه جغ مات کړم چې بوج يې په خلقو باندې دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_2.mp3', '', 1761754199, 1761754199),
(37625, 'Jeremiah 28:3', 'Jeremiah', 28, 3, 'زۀ به په دوو کالو کښې دننه دننه د مالِک خُدائ د کور هغه ټول مقدس څيزونه واپس دې ځائ ته راوړم کوم چې نبوکدنضر بادشاه بابل ته وړلى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_3.mp3', '', 1761754199, 1761754199),
(37626, 'Jeremiah 28:4', 'Jeremiah', 28, 4, 'زۀ به هم د يهوداه بادشاه د يهويقيم زوئ يهوياکين سره د يهوداه د هغه ټولو خلقو واپس دې ځائ ته راولم کوم چې په بابل کښې جلاوطن دى. بې‌شکه چې زۀ به د بابل د بادشاه جغ مات کړم. مالِک خُدائ دا فرمائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_4.mp3', '', 1761754199, 1761754199),
(37627, 'Jeremiah 28:5', 'Jeremiah', 28, 5, 'بيا يرمياه پېغمبر د اِمامانو او د هغه ټولو خلقو په مخکښې کوم چې د مالِک خُدائ په کور کښې ولاړ وُو حننياه نبى ته داسې جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_5.mp3', '', 1761754199, 1761754199),
(37628, 'Jeremiah 28:6', 'Jeremiah', 28, 6, 'هغۀ وفرمائيل چې، ”آمين. مالِک خُدائ دې هم داسې وکړى. هغه دې ستا پېشګوئې پوره او رښتيا کړى چې هغه به دوباره ټول د مالِک خُدائ د کور سامان سره د هغه کسانو چې بابل ته قېديان بوتلے شوى دى دلته واپس راولى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_6.mp3', '', 1761754199, 1761754199),
(37629, 'Jeremiah 28:7', 'Jeremiah', 28, 7, 'خو اوس تۀ هم هغه خبرو ته کومې چې زۀ تا ته د ټولو خلقو په وړاندې کوم غوږ ونيسه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_7.mp3', '', 1761754199, 1761754199),
(37630, 'Jeremiah 28:8', 'Jeremiah', 28, 8, 'زما او ستا نه ډېر وړاندې پخوانو نبيانو دا پېشګوئې کړې ده چې په ډېرو مُلکونو او لويو بادشاهتونو به جنګ، قحط او وبا راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_8.mp3', '', 1761754199, 1761754199),
(37631, 'Jeremiah 28:9', 'Jeremiah', 28, 9, 'خو کوم يو پېغمبر چې د خير او سلامتۍ پېشګوئې کوى نو هغه به په رښتيا سره په دې وپېژندلے شى چې د مالِک خُدائ له طرفه رالېږلے شوے دے کله چې د هغۀ پېشګوئې رښتيا شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_9.mp3', '', 1761754199, 1761754199),
(37632, 'Jeremiah 28:10', 'Jeremiah', 28, 10, 'نو بيا حننياه د يرمياه نبى د غاړې نه جغ لرې کړو او ټوټه ټوټه يې کړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_10.mp3', '', 1761754199, 1761754199),
(37633, 'Jeremiah 28:11', 'Jeremiah', 28, 11, 'او حننياه ټولو خلقو ته وفرمائيل چې، ”مالِک خُدائ فرمائى، زۀ به په دوو کالونو کښې دننه هم دغه شان د نبوکدنضر بادشاه جغ چې کوم هغۀ د ټولو قومونو په غاړه کښې اچولے دے لرې کړم.“ په دې خبره يرمياه د هغه ځائ نه لاړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_11.mp3', '', 1761754199, 1761754199),
(37634, 'Jeremiah 28:12', 'Jeremiah', 28, 12, 'نو بيا څۀ موده وروستو کله چې حننياه پېغمبر د يرمياه پېغمبر د څټ نه جغ مات کړو، نو بيا د مالِک خُدائ کلام په يرمياه پېغمبر نازل شو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_12.mp3', '', 1761754199, 1761754199),
(37635, 'Jeremiah 28:13', 'Jeremiah', 28, 13, '”لاړ شه او حننياه ته ووايه چې، مالِک خُدائ فرمائى، تا خو د لرګى جغ مات کړو، خو د دې په ځائ به مالِک خُدائ د خلقو په غاړه کښې د اوسپنې جغ واچوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_13.mp3', '', 1761754199, 1761754199),
(37636, 'Jeremiah 28:14', 'Jeremiah', 28, 14, 'مالِک خُدائ، ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، زۀ به د دې ټولو قومونو په غاړه کښې د اوسپنې جغ واچوم ترڅو چې هغوئ د بابل د بادشاه نبوکدنضر خِدمت وکړى. مالِک خُدائ فرمائيلى دى، تر دې چې زۀ به د ځنګل په ځناورو باندې هم نبوکدنضر ته اختيار ورکړم چې د هغۀ خِدمت وکړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_14.mp3', '', 1761754199, 1761754199),
(37637, 'Jeremiah 28:15', 'Jeremiah', 28, 15, 'بيا يرمياه نبى حننياه نبى ته وفرمائيل چې، ”حننياه ما ته غوږ شه. مالِک خُدائ تۀ نۀ يې رالېږلے، تۀ دې قوم ته د دروغو نبوت کوې او هغوئ ستاسو په دروغو باندې باور کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_15.mp3', '', 1761754199, 1761754199),
(37638, 'Jeremiah 28:16', 'Jeremiah', 28, 16, 'نو ځکه بيا مالِک خُدائ په خپله فرمائى چې، زۀ اوس تا د زمکې د مخ نه اخوا کوم. په هم دې کال کښې به تۀ مړ شې، ځکه چې تا د مالِک خُدائ خلاف د سرکشۍ تعليم ورکړے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_16.mp3', '', 1761754199, 1761754199),
(37639, 'Jeremiah 28:17', 'Jeremiah', 28, 17, 'نو د هم هغه کال په اوومه مياشت حننياه پېغمبر مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah28_verse_17.mp3', '', 1761754199, 1761754199),
(37640, 'Haggai 2:1', 'Haggai', 2, 1, 'د اوومې مياشتې په يويشتمه ورځ، د مالِک خُدائ کلام په حجى پېغمبر نازل شو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_1.mp3', '', 1761754199, 1761754199),
(37641, 'Haggai 2:2', 'Haggai', 2, 2, '”زرُبابل د شلتى‌اېل زوئ ته چې د يهوداه حکمران دے، يشوَع ته چې د مشر اِمام يهوصدق زوئ دے، او د مالِک خُدائ پاتې شوى خلقو ته ووايه. هغوئ نه تپوس وکړئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_2.mp3', '', 1761754199, 1761754199),
(37642, 'Haggai 2:3', 'Haggai', 2, 3, 'په تاسو کښې داسې څوک پاتې دى چا چې د خُدائ د دې کور مخکښې شان او شوکت ليدلے وو؟ دا تاسو ته اوس څنګه ښکارى؟ ولې دا تاسو ته هيڅ هم نۀ ښکارى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_3.mp3', '', 1761754199, 1761754199),
(37643, 'Haggai 2:4', 'Haggai', 2, 4, 'خو اوس تکړه شه، اے زرُبابله، مالِک خُدائ فرمائى چې، تکړه شه، اے يشوَع د مشر اِمام يهوصدق زويه، تکړه شه، اے د دې مُلک ټولو خلقو، مالِک خُدائ فرمائى، کار کوئ. ځکه چې زۀ ستاسو مل يم، مالِک خُدائ ربُ الافواج فرمائى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_4.mp3', '', 1761754199, 1761754199),
(37644, 'Haggai 2:5', 'Haggai', 2, 5, 'لکه څنګه چې ما تاسو سره وعده کړې وه کله چې تاسو د مِصر نه بهر راوتلئ. زما روح ستاسو په مينځ کښې دے نو تاسو مۀ يرېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_5.mp3', '', 1761754199, 1761754199),
(37645, 'Haggai 2:6', 'Haggai', 2, 6, 'مالِک خُدائ ربُ الافواج دا فرمائى چې، لږ وخت پس به زۀ آسمان او دُنيا، سمندر او اوچه زمکه وخوځوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_6.mp3', '', 1761754199, 1761754199),
(37646, 'Haggai 2:7', 'Haggai', 2, 7, 'زۀ به ټول قومونه ولړزوم، او د ټولو قومونو خزانې به راوړے شى او زۀ به دا کور د جلال نه ډک کړم، مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_7.mp3', '', 1761754199, 1761754199),
(37647, 'Haggai 2:8', 'Haggai', 2, 8, 'سپين زر زما دى او سرۀ زر هم زما دى، مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_8.mp3', '', 1761754199, 1761754199),
(37648, 'Haggai 2:9', 'Haggai', 2, 9, 'د دې موجوده کور جلال به د مخکښې کور د جلال نه زيات وى، مالِک خُدائ ربُ الافواج فرمائى. او زۀ به په دې ځائ کښې امن راولم. مالِک خُدائ ربُ الافواج فرمائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_9.mp3', '', 1761754199, 1761754199),
(37649, 'Haggai 2:10', 'Haggai', 2, 10, 'په څليريشتمه ورځ د نهمې مياشت، د داريوس د بادشاهۍ په دوېم کال، د مالِک خُدائ کلام په حجى پېغمبر نازل شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_10.mp3', '', 1761754199, 1761754199),
(37650, 'Haggai 2:11', 'Haggai', 2, 11, '”مالِک خُدائ ربُ الافواج وفرمائيل چې، اِمامانو نه تپوس وکړئ چې شريعت په دې حقله څۀ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_11.mp3', '', 1761754199, 1761754199),
(37651, 'Haggai 2:12', 'Haggai', 2, 12, 'کۀ چرې يو سړے د قربانۍ نه مقدسه غوښه په خپله لمنه کښې واچوى او چرته يې وړى، او د هغۀ لمن روټۍ يا ترکارۍ، ميو، تېلو يا نور د خوراک څيزونو سره ولګى، آيا دا څيزونه به هم مقدس شى؟“ نو اِمامانو په جواب کښې ووئيل چې، ”نه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_12.mp3', '', 1761754199, 1761754199),
(37652, 'Haggai 2:13', 'Haggai', 2, 13, 'بيا حجى وفرمائيل، ”کۀ چرې يو سړے د مړى سره په لګېدو باندې ناپاک شى بيا کۀ هغه په دې کښې څۀ څيز سره ولګيږى، آيا دا به ناپاک شى؟“ ”آو،“ اِمامانو جواب ورکړو، ”دا به ناپاک شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_13.mp3', '', 1761754199, 1761754199),
(37653, 'Haggai 2:14', 'Haggai', 2, 14, 'بيا حجى وفرمائيل، ”زما په نظر کښې د دې خلقو او د دې قوم هم دا حال دے. مالِک خُدائ فرمائى چې، دوئ چې څۀ کوى او څۀ قربانى کوى هغه ناپاک دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_14.mp3', '', 1761754199, 1761754199),
(37654, 'Haggai 2:15', 'Haggai', 2, 15, 'د دې نه وړاندې چې د مالِک خُدائ د کور د بنياد کاڼى يو په بل نۀ وُو اېښودلے شوى، اوس دې خبرې ته ښۀ خيال وکړئ چې ستاسو به څۀ حال وو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_15.mp3', '', 1761754199, 1761754199),
(37655, 'Haggai 2:16', 'Haggai', 2, 16, 'کله چې تاسو د غلې د شلو بورو په اُميد راغلى وئ، نو هلته صرف لس بورۍ وې. کۀ څوک د ميو چاټۍ ته راغلو چې سل ليټره ترې راوباسى، او هلته صرف پنځوس ليټره وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_16.mp3', '', 1761754199, 1761754199),
(37656, 'Haggai 2:17', 'Haggai', 2, 17, 'ما ستاسو د لاس په ټولو کارونو، تِليا او پپونکې او ږلۍ راوسته. خو تاسو بيا هم ما ته واپس رانۀ غلئ، مالِک خُدائ دا فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_17.mp3', '', 1761754199, 1761754199),
(37657, 'Haggai 2:18', 'Haggai', 2, 18, 'تاسو په دې نننۍ ورځ چې د نهمې مياشتې څليريشتم تاريخ دے سوچ وکړئ، کله چې په دې ورځ د مالِک خُدائ د کور بنياد کېښودلے شو. په دې فکر وکړئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_18.mp3', '', 1761754199, 1761754199),
(37658, 'Haggai 2:19', 'Haggai', 2, 19, 'زۀ اوس تاسو سره وعده کوم په دې وخت کښې چې غله لا په ګودام کښې شته، تاسو تر اوسه پورې خپل فصل نۀ دے لو کړے، او ستاسو د انګورو بوټو او د اينځرو ونو، انار او د زيتُونو ونو هيڅ مېوه لا نۀ ده کړې. خو د نن نه به زۀ تاسو له برکت درکړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_19.mp3', '', 1761754199, 1761754199),
(37659, 'Haggai 2:20', 'Haggai', 2, 20, 'په هم هغه ورځ د هغې مياشتې په څليريشتمه ورځ د مالِک خُدائ کلام په دوېم ځل په حجى نازل شو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_20.mp3', '', 1761754199, 1761754199),
(37660, 'Haggai 2:21', 'Haggai', 2, 21, '”زرُبابل ته ووايه چې د يهوداه حکمران دے چې زۀ به آسمان او زمکه وخوځوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_21.mp3', '', 1761754199, 1761754199),
(37661, 'Haggai 2:22', 'Haggai', 2, 22, 'زۀ به شاهى تختونه اولټه کړم او د پردو حکومتونو طاقت به ختم کړم. زۀ به جنګى ګاډۍ او د دې چلوونکى په بل مخ واړوم، آسونه او د دې سوارۀ به يو بل ووژنى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_22.mp3', '', 1761754199, 1761754199),
(37662, 'Haggai 2:23', 'Haggai', 2, 23, 'مالِک خُدائ ربُ الافواج فرمائى چې، زۀ به تا په هغه ورځ بوځم، زما خِدمت کوونکى زرُبابل د شلتى‌اېل زويه، مالِک خُدائ فرمائى، او زۀ به تا لکه د خپل مهر د ګوتې په شان کړم، ځکه چې تۀ ما خوښ کړے يې. مالِک خُدائ ربُ الافواج دا فرمائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai2_verse_23.mp3', '', 1761754199, 1761754199),
(37663, 'Psalms 102:1', 'Psalms', 102, 1, 'ای څښتنه کړه قبوله زما دعا زما فریاد دې تاته ورسیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_1.mp3', '', 1761754199, 1761754199),
(37664, 'Psalms 102:2', 'Psalms', 102, 2, 'په سخته ورځ کې دې مخ مه اړوه زما نه ماته غوږ ونیسه کله چې تاته کړم دعا ته یې قبوله کړه زر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_2.mp3', '', 1761754199, 1761754199),
(37665, 'Psalms 102:3', 'Psalms', 102, 3, 'فنا کیږي زما ژوند لکه لوګي په شان د سور انګار په څېر مې سوځي د بدن هډوکي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_3.mp3', '', 1761754199, 1761754199),
(37666, 'Psalms 102:4', 'Psalms', 102, 4, 'د واښو په څېر مې زړه مات، مړاوی شوی رانه هېر دي چې ډوډۍ مې وخورم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_4.mp3', '', 1761754199, 1761754199),
(37667, 'Psalms 102:5', 'Psalms', 102, 5, 'په لوړ اواز باندې د زګېرویو له امله صرف پوستکی او هډوکي مې بدن کې پاتې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_5.mp3', '', 1761754199, 1761754199),
(37668, 'Psalms 102:6', 'Psalms', 102, 6, 'د صحرایي ګونګي په شان یمه زه هغه ګونګی چې کنډوالو کې اوسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_6.mp3', '', 1761754199, 1761754199),
(37669, 'Psalms 102:7', 'Psalms', 102, 7, 'خوب مې له سترګو تښتېدلی هغې مرغۍ په شان یم چې اوسي ځانله په بام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_7.mp3', '', 1761754199, 1761754199),
(37670, 'Psalms 102:8', 'Psalms', 102, 8, 'دښمنان ټوله ورځ پېغور راکوي هغوی چې ما باندې ملنډې وهي لعنت ویلو کې زما نوم اخلي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_8.mp3', '', 1761754199, 1761754199),
(37671, 'Psalms 102:11', 'Psalms', 102, 11, 'تېریږي عمر مې په څېر د مازدیګر د لمر او مړاوی کېږم د واښو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_11.mp3', '', 1761754199, 1761754199),
(37672, 'Psalms 102:12', 'Psalms', 102, 12, 'خو ای څښتنه ته په تخت ناست به یې تل ترتله ټولو نسلونو پورې به پاتې شي د ستا یادونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_12.mp3', '', 1761754199, 1761754199),
(37673, 'Psalms 102:13', 'Psalms', 102, 13, 'ته راپاڅېږې به او رحم په صهیون به وکړې اوس د دې وخت دی مهربانه په هغه چې شې ته ټاکلی وخت رارسېدلی دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_13.mp3', '', 1761754199, 1761754199),
(37674, 'Psalms 102:14', 'Psalms', 102, 14, 'د هغه تیږې هم دي ګرانې په بندګانو ستا او د هغه په خاوره باندې هم کړي رحم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_14.mp3', '', 1761754199, 1761754199),
(37675, 'Psalms 102:15', 'Psalms', 102, 15, 'ولسونه به وېریږي د څښتن له نومه او د نړۍ ټول پاچاهان به یې وېریږي له جلاله څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_15.mp3', '', 1761754199, 1761754199),
(37676, 'Psalms 102:16', 'Psalms', 102, 16, 'څښتن چې کله د صهیون ښار یوځل بیا جوړ کړي نو خپل جلال به کړي ښکاره خلکو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_16.mp3', '', 1761754199, 1761754199),
(37677, 'Psalms 102:17', 'Psalms', 102, 17, 'واوري زاري به د بې‌وزلو او د اړو خلکو په سپکه سترګه به ونه ګوري د دوی دعا ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_17.mp3', '', 1761754199, 1761754199),
(37678, 'Psalms 102:18', 'Psalms', 102, 18, 'راتلونکي نسل ته دې ولیکل شي چې څښتن څه کړي دي ترڅو ثنا ووایي څښتن ته هغوی چې لا تر‌اوسه زېږېدلي نه دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_18.mp3', '', 1761754199, 1761754199),
(37679, 'Psalms 102:19', 'Psalms', 102, 19, 'څښتن وکتل له خپل سپېڅلي ځایه پاس له اسمان څخه یې وکتل د ځمکې په لور', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_19.mp3', '', 1761754199, 1761754199),
(37680, 'Psalms 102:20', 'Psalms', 102, 20, 'ترڅو زګېروي د زندانیانو واوري او خلاص کړي هغوی چې وو محکوم په مرګ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_20.mp3', '', 1761754199, 1761754199),
(37681, 'Psalms 102:21', 'Psalms', 102, 21, 'نو له دې وجې به صهیون کې خلک یاد کاندي نامه د څښتن ثنا او صفت به یې اورشلیم کې وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_21.mp3', '', 1761754199, 1761754199),
(37682, 'Psalms 102:22', 'Psalms', 102, 22, 'چې شي راټول قومونه او د پاچاهیو خلک ترڅو څښتن ته عبادت وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_22.mp3', '', 1761754199, 1761754199),
(37683, 'Psalms 102:23', 'Psalms', 102, 23, 'څښتن په نیمه لار کې واخیست زما ځواک راڅخه او زما ورځې یې کړې لنډې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_23.mp3', '', 1761754199, 1761754199),
(37684, 'Psalms 102:24', 'Psalms', 102, 24, 'نو ما وویل: «ای زما خدایه په ځوانۍ کې رانه ژوند مه اخله! ته ای څښتنه یې تر ابده ژوندی»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_24.mp3', '', 1761754199, 1761754199),
(37685, 'Psalms 102:25', 'Psalms', 102, 25, 'له ډېر پخوا څخه دې ایښی ؤ بنیاد د ځمکې او اسمانونه دې کړل جوړ خپلو لاسونو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_25.mp3', '', 1761754199, 1761754199),
(37686, 'Psalms 102:26', 'Psalms', 102, 26, 'هغوی فنا به شي خو ته به پاتې شې هغوی به ټول لکه لباس زاړه شي ته به بدل کړې هغوی لکه چپنې په شان او هغوی به شي فنا له سترګو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_26.mp3', '', 1761754199, 1761754199),
(37687, 'Psalms 102:27', 'Psalms', 102, 27, 'خو پاتې کېږې په خپل حال ته مدام او پای به ونه لري هېڅ دا ستا دوران', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_27.mp3', '', 1761754199, 1761754199),
(37688, 'Psalms 102:28', 'Psalms', 102, 28, 'اوسیږي امن کې به ستا د بندګانو اولاد وي به قایم او دایم اولاده د دوی ستا تر نظر لاندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms102_verse_28.mp3', '', 1761754199, 1761754199),
(37689, 'Psalms 82:1', 'Psalms', 82, 1, 'خدای دی ناست په اسماني دربار کې نورو قومونو د خدایانو ترمنځ کړي قضاوت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms82_verse_1.mp3', '', 1761754199, 1761754199),
(37690, 'Psalms 82:2', 'Psalms', 82, 2, '«بې‌انصافۍ سره ترڅو به تاسو کړئ قضاوت او د بدکارو طرفداري به کوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms82_verse_2.mp3', '', 1761754199, 1761754199),
(37691, 'Psalms 82:3', 'Psalms', 82, 3, 'د غریبانو یتیمانو د حقونو نه ساتنه وکړئ کوئ انصاف د محتاجانو او بې‌وزلو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms82_verse_3.mp3', '', 1761754199, 1761754199),
(37692, 'Psalms 82:4', 'Psalms', 82, 4, 'خلاص کړئ بې‌وزله او غریب انسانان د شریرانو د منګولو څخه خلاص کړئ هغوی»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms82_verse_4.mp3', '', 1761754199, 1761754199),
(37693, 'Psalms 82:5', 'Psalms', 82, 5, 'څومره جاهل، څومره کم‌عقل دي هغوی! دوی دي بالکل فاسدان او د ځمکې مخ نه دی ورک شوی انصاف', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms82_verse_5.mp3', '', 1761754199, 1761754199),
(37694, 'Psalms 82:6', 'Psalms', 82, 6, 'ما ویل: «تاسو خو خدایان یئ ټول د خدای تعالی بچیان یئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms82_verse_6.mp3', '', 1761754199, 1761754199),
(37695, 'Psalms 82:7', 'Psalms', 82, 7, 'خو مړه به شئ د انسانانو په شان ژوند به مو ختم شي د نورو واکمنانو په شان»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms82_verse_7.mp3', '', 1761754199, 1761754199),
(37696, 'Psalms 82:8', 'Psalms', 82, 8, 'خدایه راپاڅه د دې ځمکې عدالت وکړه د ټولو قومونو د اختیار خاوند یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms82_verse_8.mp3', '', 1761754199, 1761754199),
(37697, 'Isaiah 48:1', 'Isaiah', 48, 1, 'ای د یعقوب اولادې چې یادېږئ په نامه د اسراییلو ای د یهودا اولادې تاسو قسم خورئ د څښتن په نامه او کوئ ذکر او عبادت د اسراییلو د خدای خو په رښتیا او صداقت سره نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_1.mp3', '', 1761754199, 1761754199),
(37698, 'Isaiah 48:2', 'Isaiah', 48, 2, 'خو بیاهم ویاړئ په دې چې اوسېدونکي د سپېڅلي ښار یئ او تاسو تکیه کوئ د اسراییلو په خدای چې نوم یې دی مطلق قادر څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_2.mp3', '', 1761754199, 1761754199),
(37699, 'Isaiah 48:3', 'Isaiah', 48, 3, 'څښتن وایي د اسراییلو قوم ته: «ما پېشګویي کړې وه ډېره پخوا او اعلان مې کړی ؤ چې پېښیږي به څه بیا مې ناڅاپه عملي کړلې دا او زما ټولي پېشګویۍ شوې رښتیا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_3.mp3', '', 1761754199, 1761754199),
(37700, 'Isaiah 48:4', 'Isaiah', 48, 4, 'ځکه چې زه پوهېدم چې تاسو څومره یئ سرکښه خلک او یئ کلک لکه د اوسپنې په شان او نه نرمېدونکي یئ د برنجو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_4.mp3', '', 1761754199, 1761754199),
(37701, 'Isaiah 48:5', 'Isaiah', 48, 5, 'او ما پېشګویي کړې وه ستاسو د راتلونکې په هکله له ډېر پخوا نه اعلان مې کړی ؤ د هغو پېښو چې دي شوي د دې دپاره چې دعوه ونه کړئ چې دا هرڅه کړي ستاسو بتانو او شوي ستاسو د فلزي مجسمو په امر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_5.mp3', '', 1761754199, 1761754199),
(37702, 'Isaiah 48:6', 'Isaiah', 48, 6, 'تاسو زما پېشګویۍ واورېدلې اوس یې وګورئ چې پوره شوې ټولې باید په دې باندې اقرار وکړئ چې پېشګویۍ وې زما سمې اعلانوم تاسو ته نوي شیان له دې نه وروسته هغه څه چې وو پټ له تاسو او خبر نه وئ له هغو نه تاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_6.mp3', '', 1761754199, 1761754199),
(37703, 'Isaiah 48:7', 'Isaiah', 48, 7, 'یوازې اوس منځ ته راوړمه هغه ټول شیان چې تاسو نه وو اورېدلي تېرو وختونو کې که چېرې تاسو اورېدلي وای نو تاسو کړې به دعوه وای چې مونږ خبر وو له دې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_7.mp3', '', 1761754199, 1761754199),
(37704, 'Isaiah 48:8', 'Isaiah', 48, 8, 'نه، تاسو په دې اړه هېڅ نه دي اورېدلي او خبر نه یئ هېڅ په دې هکله ځکه چې زه پوهېدم چې خاینان یئ تاسو او مشهور وئ د یاغیانو په نوم د مور له ګېډې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_8.mp3', '', 1761754199, 1761754199),
(37705, 'Isaiah 48:9', 'Isaiah', 48, 9, 'خو د خپل نوم په خاطر ډډه کومه زه له خپلې غوسې د خپل ثنا او صفت په خاطر زه مخنیوی کوم له خپلې غوسې او له منځه نه وړم تاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_9.mp3', '', 1761754199, 1761754199),
(37706, 'Isaiah 48:10', 'Isaiah', 48, 10, 'ګورئ، ما تاسو پاک کړئ، خو نه په شان د سپینو زرو تاسو مې وازمایلئ د کړاوونو داش کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_10.mp3', '', 1761754199, 1761754199),
(37707, 'Isaiah 48:11', 'Isaiah', 48, 11, 'څه چې کوم هغه کوم زه د خپل ځان په خاطر یوازې کړم یې د خپل ځان په خاطر ځکه زه نه پرېږدم چې بې عزتي مې وشي او زه به ورنه کړم خپل جلال هېچا ته»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_11.mp3', '', 1761754199, 1761754199),
(37708, 'Isaiah 48:12', 'Isaiah', 48, 12, 'څښتن وایي: «ای یعقوبه، ای اسراییله، ای زما قومه چې ما راغوښتي یئ واورئ! یوازېنی خدای یمه زه اول او اخر یمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_12.mp3', '', 1761754199, 1761754199),
(37709, 'Isaiah 48:13', 'Isaiah', 48, 13, 'هو، ما بنیاد ایښی د ځمکې خپلو لاسونو باندې او ما خپاره کړي اسمانونه دي کله چې زه هغوی راغواړمه نو راځي او حاضروي ځانونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_13.mp3', '', 1761754199, 1761754199),
(37710, 'Isaiah 48:14', 'Isaiah', 48, 14, 'سره راغونډ شئ تاسو ټول او واورئ! په خدایانو کې چا وکړه پېشګویي د دغو پېښو؟ د کوم سړي سره چې مینه لرم هغه تر سره به کړي بابل باندې زما اراده او د هغه قدرت به کاندي ړنګه د بابل پاچاهي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_14.mp3', '', 1761754199, 1761754199);